pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(value) = bytes.strip_prefix("{\"v\":2,\"type\":\"hello\",\"value\":\"") {
        if let Some(value) = value.strip_suffix("\"}") {
            return Ok(Msg::Hello(value.to_string()));
        }
    }
    if let Some(sequence) = bytes.strip_prefix("{\"v\":2,\"type\":\"heartbeat\",\"sequence\":") {
        if let Some(sequence) = sequence.strip_suffix("}") {
            if let Ok(sequence) = sequence.parse() {
                return Ok(Msg::Heartbeat(sequence));
            }
        }
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("{{\"v\":2,\"type\":\"hello\",\"value\":\"{}\"}}", value),
        Msg::Heartbeat(sequence) => format!("{{\"v\":2,\"type\":\"heartbeat\",\"sequence\":{}}}", sequence),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn heartbeat_roundtrip() {
        assert!(matches!(decode(&encode(&Msg::Heartbeat(42))), Ok(Msg::Heartbeat(42))));
    }
}
